unitTests:
test("valid names", () => {
  for (const n of ["ada_99", "Bob", "x_y", "abcdefghijklmnop"]) check(isValidUsername(n), n);
});

test("invalid names", () => {
  for (const n of ["9lives", "al", "", "_ada", "ada-lovelace", "abcdefghijklmnopq", "ada lovelace", "adé"]) check(!isValidUsername(n), n);
});

